import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import { join, resolve, sep } from 'node:path';

/**
 * Where uploaded documents live, behind an interface (D8). Production uses private, encrypted
 * S3 in af-south-1 with short-lived signed links (planning.md §16.1, `S3FileStore` in s3.ts);
 * locally, files go to a folder on disk, and tests keep them in memory. All three meet the same
 * contract (storage.contract.ts).
 *
 * Keys are generated by the app, never taken from a user, and must be plain identifiers, so a
 * key can never reach outside the store's folder.
 */

export interface StoredFile {
  readonly bytes: Uint8Array;
  readonly mimeType: string;
}

export interface FileStore {
  put(key: string, file: StoredFile): Promise<void>;
  get(key: string): Promise<StoredFile | null>;
  delete(key: string): Promise<void>;
}

const KEY = /^[a-z0-9][a-z0-9-]{7,127}$/;

export class InvalidKeyError extends Error {
  override readonly name = 'InvalidKeyError';
}

export function assertKey(key: string): void {
  if (!KEY.test(key))
    throw new InvalidKeyError('A storage key is lower-case letters, digits and hyphens');
}

export class MemoryFileStore implements FileStore {
  readonly #files = new Map<string, StoredFile>();

  async put(key: string, file: StoredFile): Promise<void> {
    assertKey(key);
    this.#files.set(key, { bytes: new Uint8Array(file.bytes), mimeType: file.mimeType });
  }

  async get(key: string): Promise<StoredFile | null> {
    assertKey(key);
    return this.#files.get(key) ?? null;
  }

  async delete(key: string): Promise<void> {
    assertKey(key);
    this.#files.delete(key);
  }
}

/** Local development: one file per key, plus its type, in a folder that git ignores. */
export class DiskFileStore implements FileStore {
  readonly #root: string;

  constructor(root: string) {
    this.#root = resolve(root);
  }

  #path(key: string): string {
    assertKey(key);
    const path = resolve(join(this.#root, key));
    if (!path.startsWith(this.#root + sep)) throw new InvalidKeyError('Key escapes the store');
    return path;
  }

  async put(key: string, file: StoredFile): Promise<void> {
    const path = this.#path(key);
    await mkdir(this.#root, { recursive: true });
    await writeFile(path, file.bytes);
    await writeFile(`${path}.type`, file.mimeType, 'utf8');
  }

  async get(key: string): Promise<StoredFile | null> {
    const path = this.#path(key);
    try {
      const [bytes, mimeType] = await Promise.all([
        readFile(path),
        readFile(`${path}.type`, 'utf8'),
      ]);
      return { bytes: new Uint8Array(bytes), mimeType };
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === 'ENOENT') return null;
      throw error;
    }
  }

  async delete(key: string): Promise<void> {
    const path = this.#path(key);
    await rm(path, { force: true });
    await rm(`${path}.type`, { force: true });
  }
}
